{
  "name": "search_orders",
  "description": "ค้นคำสั่งซื้อของลูกค้าด้วยอีเมล ใช้เมื่อลูกค้าถามสถานะหรือประวัติคำสั่งซื้อ คืนรายการล่าสุดไม่เกิน 10 รายการ (เลขคำสั่งซื้อ วันที่ สถานะ ยอดรวม)",
  "input_schema": {
    "type": "object",
    "properties": {
      "email": {
        "type": "string",
        "description": "อีเมลที่ลูกค้าใช้สั่งซื้อ"
      },
      "status": {
        "type": "string",
        "enum": ["pending", "shipped", "delivered"],
        "description": "กรองตามสถานะ (ไม่ระบุ = ทุกสถานะ)"
      }
    },
    "required": ["email"]
  }
}
